from collections import Counter
from robot.libraries.BuiltIn import BuiltIn

from taf.rfrl.procedures.resources.python.hw_info.exceptions import RmodNotFound, DifferentRmodCount, \
    ProductCodesDoNotMatch, DifferentSmodCount, DifferentSmodsDetected, SerialNumbersAndProductCodesDoNotMatch
from taf.rfrl.procedures.resources.python.logger.logger import log_input_and_output, log_operation, log_result, log_env_state, log_step
from taf.rfrl.procedures.resources.python.admin_info_model.admin_info_model import get_serial_numbers_of_all_smods, \
    get_serial_numbers_and_product_codes_of_all_modules
from taf.rfrl.procedures.resources.python.testline.TestLine import TestLine


def get_rmod_serial_numbers_and_product_codes(bts_type="GNB"):
    """
    Gets serial numbers and product codes of RMODs from init file.
    :param bts_type: type of BTS setup
    :type bts_type: str, GNB or ENB
    :return: dictionary with RMODs' serial numbers as keys and product codes as values, e.g. :
    {"EA203150671": "473807A.101", "EA213750671": "473807A.102"}
    :rtype: dict
    """
    rmods = TestLine().get_radios_configs(bts_type)
    return {rmod.serial_number: rmod.product_code for rmod in rmods}


@log_input_and_output
def compare_serial_numbers_and_product_codes_of_rmods(init_rmods_info, admin_rmods_info):
    """
    Compares RMODs' info about serial numbers and product codes provided in init_rmods_info and admin_rmods_info.
    :param init_rmods_info: dictionary with RMODs' serial numbers as keys and product codes as values got from init
    :type init_rmods_info: dict
    :param admin_rmods_info: dictionary with RMODs' serial numbers as keys and product codes as values got from admin
    :type admin_rmods_info: dict
    :raises: ProductCodesDoNotMatch when product codes for radio module do not match
    :raises: RmodNotFound when information about radio module with provided serial number could not be found in one of
    RMODs' dicts
    """
    _compare_number_of_rmods(init_rmods_info, admin_rmods_info)

    for init_serial_number, init_product_code in init_rmods_info.items():
        try:
            if admin_rmods_info[init_serial_number] != init_product_code:
                raise ProductCodesDoNotMatch("Product codes for radio module with SN: {} do not match. Product code "
                                             "provided in init: {}, product code read via admin: {}".
                                             format(init_serial_number, init_product_code,
                                                    admin_rmods_info[init_serial_number]))

        except KeyError:
            raise RmodNotFound("RMOD defined in init with serial number: {} could not be found via admin.".
                               format(init_serial_number))

    log_result("Validation of RMODs' serial numbers and product codes finished successfully.")


@log_input_and_output
def compare_serial_numbers_and_product_codes_of_all_modules(connection, bts_type='GNB', is_simulated=False):
    """
    Compares serial numbers and product codes of all modules (CABINET, SMOD, BBMOD, RMOD, ASIRMOD) from init file and admin.
    If any SMOD, BBMOD, RMOD or ASIRMOD do not have serial number or product code defined in init file, then it will not be compared.
    If any CABINET does not have product code defined in init file, then it will not be compared.
    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :param bts_type: BTS type 'GNB' or 'ENB' of which the modules serial numbers and product codes should be compared;
                     defaults to 'GNB'.
    :type bts_type: str
    :param is_simulated: indicates whether simulators are used in BTS;
                         if set to True, then RMODs comparison is skipped;
                         defaults to False (RMODs comparison is performed).
    :type is_simulated: bool
    :raises: SerialNumbersAndProductCodesDoNotMatch when at least one serial number or product code of any module do not match
    """
    log_operation("Validating serial numbers and product codes of all modules")
    errors = []
    test_line = TestLine()
    serial_numbers_and_product_codes_from_admin = get_serial_numbers_and_product_codes_of_all_modules(connection)

    _compare_product_codes_of_cabinets(serial_numbers_and_product_codes_from_admin, test_line, bts_type, errors)
    _compare_serial_numbers_and_product_codes_of_smods(serial_numbers_and_product_codes_from_admin, test_line, bts_type, errors)
    _compare_serial_numbers_and_product_codes_of_bbmods(serial_numbers_and_product_codes_from_admin, test_line, bts_type, errors)

    if not is_simulated:
        _compare_serial_numbers_and_product_codes_of_rmods(serial_numbers_and_product_codes_from_admin, test_line, bts_type, errors)

    if errors:
        raise SerialNumbersAndProductCodesDoNotMatch(
            "Errors occurred during validation of modules serial numbers and product codes:\n{}".format("\n".join(errors)))
    else:
        log_result("Validation of all modules serial numbers and product codes finished successfully.")


@log_input_and_output
def get_mrbts_id(bts_id=0):
    """
    Gets mrbts id from init file.
    :param bts_id: BTS(eNB/gNB) id - related to Test Line configuration, defaults to 0
    :type bts_id: int or str
    :return: MRBTS id number
    :rtype: int
    """
    return BuiltIn().get_variable_value('${tl}').gnbs[int(bts_id)].instance_id


@log_input_and_output
def compare_smods_serial_numbers(connection, bts_type='GNB'):
    """
    Compares SMODs' serial numbers from init file and admin.
    :param bts_type: BTS type 'GNB' or 'ENB' of which the smods serial numbers should be returned;
                     default value 'GNB'.
    :type bts_type: str.
    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str.
    :raises: DifferentSmodsDetected when SMODs serial numbers do not match.
    :raises: DifferentSmodCount when number of SMODs serial numbers do not match.
    """
    admin_serial_numbers = get_serial_numbers_of_all_smods(connection)
    test_line = TestLine()
    init_serial_numbers = test_line.get_serial_numbers_of_all_smods_from_init(bts_type)
    log_env_state("List of SMODs serial numbers via admin: {},"
                  " list of SMODs serial numbers from init: {}".format(admin_serial_numbers, init_serial_numbers))
    if len(admin_serial_numbers) == len(init_serial_numbers):
        if sorted(admin_serial_numbers) != sorted(init_serial_numbers):
            raise DifferentSmodsDetected("SMOD serial numbers got via admin: {} differ from serial numbers got via "
                                         "init: {}. Please check your init file and SCF.".format(admin_serial_numbers,
                                                                                                 init_serial_numbers))
    else:
        raise DifferentSmodCount("Number of SMODs serial numbers via admin: {} and serial numbers via init: "
                                 "{} does not match. Please check your init file and SCF.".format(admin_serial_numbers,
                                                                                                  init_serial_numbers))
    log_result("SMODs serial numbers in init file and SCF are equal")


def _compare_number_of_rmods(init_rmods_info, admin_rmods_info):
    if len(init_rmods_info) != len(admin_rmods_info):
        raise DifferentRmodCount("Number of radio modules read from init: {} is different than number read from admin:"
                                 " {}. Please review your init file.".format(len(init_rmods_info),
                                                                             len(admin_rmods_info)))


def _compare_product_codes_of_cabinets(serial_numbers_and_product_codes_from_admin, test_line, bts_type, errors):
    """
    Compares product codes of CABINETs from init file and admin.
    :param serial_numbers_and_product_codes_from_admin: dictionary with serial numbers and product codes of all modules from admin, e.g. :
                                                        {'CABINETs': [{'product_code': '473098A'},
                                                                      {'product_code': '473098B'}],
                                                         'SMODs': [{'serial_number': 'L1232304192', 'product_code': '474767A.103'},
                                                                   {'serial_number': 'L1232304183', 'product_code': '474767X.101'}],
                                                         'BBMODs': [{'serial_number': 'L1232004108', 'product_code': '475792A.101'},
                                                                    {'serial_number': 'L1232004111', 'product_code': '475792A.103'}],
                                                         'RMODs': [{'serial_number': 'AH221500786', 'product_code': '475432A.101'},
                                                                   {'serial_number': 'AH221500678', 'product_code': '475432A.103'}]}
    :type serial_numbers_and_product_codes_from_admin: dict[str, list[dict[str, str]]]
    :param test_line: gives access to testline data from init file
    :type test_line: TestLine
    :param bts_type: BTS type 'GNB' or 'ENB' of which CABINETs product codes should be compared
    :type bts_type: str
    :param errors: collective list of errors found during every comparison; if error is found, it is added to the list
    :type errors: list[str]
    """
    if cabinets_product_codes_from_init := test_line.get_product_codes_of_all_cabinets_from_init(bts_type):
        error = _compare_product_codes(cabinets_product_codes_from_init,
                                       serial_numbers_and_product_codes_from_admin['CABINETs'],
                                       modules='CABINETs')
        errors.append(error) if error else None
    else:
        log_step("No product codes for CABINETs in init file, skipping their comparison")


