@log_input_and_output
def _compare_product_codes(init_product_codes, admin_product_codes, modules):
    """
    Compares product codes of modules from init file and admin.
    :param init_product_codes: product codes from init file, e.g. ['473098A', '473098B']
    :type init_product_codes: list[str]
    :param admin_product_codes: product codes from admin, e.g. [{'product_code': '473098A'}, {'product_code': '473098B'}]
    :type admin_product_codes: list[dict[str, str]]
    :param modules: name of modules of which product codes will be compared, e.g. 'CABINETs'
    :type modules: str
    :return: error message if product codes do not match, empty string if product codes match
    :rtype: str
    """
    admin_product_codes = [product_code['product_code'] for product_code in admin_product_codes]
    log_env_state(f"List of {modules} product codes from init: {init_product_codes}, "
                  f"list of {modules} product codes read via admin: {admin_product_codes}")

    init_product_codes_counter = Counter(init_product_codes)
    admin_product_codes_counter = Counter(admin_product_codes)

    for product_code, init_product_code_count in init_product_codes_counter.items():
        if admin_product_codes_counter.get(product_code, 0) < init_product_code_count:
            return f"Product codes for {modules} do not match. Product codes provided in init: {init_product_codes}, " \
                   f"product codes read via admin: {admin_product_codes}"

    log_result(f"All {modules} product codes from init file are present in product codes read via admin")
    return ""


@log_input_and_output
def _compare_serial_numbers_and_product_codes(init_serial_numbers_and_product_codes, admin_serial_numbers_and_product_codes, modules):
    """
    Compares serial numbers and product codes of modules from init file and admin.
    :param init_serial_numbers_and_product_codes: serial numbers and product codes from init file,
                                                  e.g. {'L1232304192':'474767A.103',
                                                        'L1232304183':'474767A.101'}
    :type init_serial_numbers_and_product_codes: dict[str, str]
    :param admin_serial_numbers_and_product_codes: serial numbers and product codes from admin,
                                                   e.g. [{'serial_number': 'L1232304192', 'product_code':'474767A.103'},
                                                         {'serial_number': 'L1232304183', 'product_code':'474767A.101'}]
    :type admin_serial_numbers_and_product_codes: list[dict[str, str]]
    :param modules: name of modules of which serial numbers and product codes will be compared, e.g. 'SMODs', 'BBMODs', 'RMODs'
    :type modules: str
    :return: error message if serial numbers and product codes do not match, empty string if serial numbers and product codes match
    :rtype: str
    """
    admin_serial_numbers_and_product_codes = {serial_number_and_product_code['serial_number']: serial_number_and_product_code['product_code']
                                              for serial_number_and_product_code in admin_serial_numbers_and_product_codes}
    log_env_state(f"List of {modules} serial numbers and product codes from init: {init_serial_numbers_and_product_codes}, "
                  f"list of {modules} serial numbers and product codes read via admin: {admin_serial_numbers_and_product_codes}")

    for init_serial_number, init_product_code in init_serial_numbers_and_product_codes.items():
        admin_product_code = admin_serial_numbers_and_product_codes.get(init_serial_number)
        if admin_product_code != init_product_code:
            return f"Serial numbers and product codes for {modules} do not match. " \
                   f"Serial numbers and product codes provided in init: {init_serial_numbers_and_product_codes}, " \
                   f"serial numbers and product codes read via admin: {admin_serial_numbers_and_product_codes}"

    log_result(f"All {modules} serial numbers and product codes from init file are present in serial numbers and product codes read via admin")
    return ""
